{"explanation":"A secant line goes through two points on the curve, P = (x₀, f(x₀)) and Q = (x₀+h, f(x₀+h)). Its slope is the difference quotient [f(x₀+h) − f(x₀)] / h. As h gets smaller, Q slides along the curve toward P, and the secant (orange) turns until it matches the tangent line (green). In the limit h → 0, the secant slope equals the derivative f′(x₀). The animation shrinks h automatically. You can then use the sliders to change h and x₀, or press the button to watch the limit again.","manimCode":"const f = (x) => 0.25 * x * x + 0.5;
const df = (x) => 0.5 * x;

const axes = new Axes({ xRange: [-1, 5, 1], yRange: [-1, 6, 1], xLength: 8, yLength: 5.5, tips: false });
axes.shift([-1.8, -0.3, 0]);
const curve = axes.plot(f, { color: BLUE });
scene.add(axes, curve);

let x0 = 1.5;
let h = 2;
let showTangent = true;

const L = 4;
function lineThrough(x, y, m) {
  const P = axes.c2p(x, y);
  const R = axes.c2p(x + 1, y + m);
  let dx = R[0] - P[0], dy = R[1] - P[1];
  const n = Math.hypot(dx, dy) || 1;
  dx /= n; dy /= n;
  return [[P[0] - L * dx, P[1] - L * dy, 0], [P[0] + L * dx, P[1] + L * dy, 0]];
}

const tangent = new Polygon({ vertices: [[0,0,0],[1,0,0]], color: GREEN });
tangent.setStrokeWidth(2).setFillOpacity(0);
const secant = new Polygon({ vertices: [[0,0,0],[1,0,0]], color: ORANGE });
secant.setStrokeWidth(4).setFillOpacity(0);
const runSeg = new Polygon({ vertices: [[0,0,0],[1,0,0]], color: GRAY });
runSeg.setStrokeWidth(2).setFillOpacity(0);
const riseSeg = new Polygon({ vertices: [[0,0,0],[1,0,0]], color: GRAY });
riseSeg.setStrokeWidth(2).setFillOpacity(0);
const dotP = new Dot({ point: axes.c2p(x0, f(x0)), color: YELLOW });
const dotQ = new Dot({ point: axes.c2p(x0 + h, f(x0 + h)), color: RED });

scene.add(tangent, runSeg, riseSeg, secant, dotP, dotQ);

const formula = new MathTex({ latex: 'm_{\\text{sec}} = \\frac{f(x_0+h)-f(x_0)}{h}', color: WHITE });
await formula.waitForRender();
formula.scale(0.7);
formula.moveTo([4.3, -1.2, 0]);
scene.add(formula);

let info = null;
let lastStr = '';
function updateInfo() {
  const ms = Math.abs(h) < 1e-6 ? df(x0) : (f(x0 + h) - f(x0)) / h;
  const str = 'h = ' + h.toFixed(2) + '\nsecant slope = ' + ms.toFixed(3) + '\ntangent slope = ' + df(x0).toFixed(3);
  if (str === lastStr) return;
  lastStr = str;
  if (info) scene.remove(info);
  info = new Text({ text: str, color: WHITE, fontSize: 22 });
  info.moveTo([4.3, -2.6, 0]);
  scene.add(info);
}

function update() {
  const y0 = f(x0);
  const x1 = x0 + h, y1 = f(x1);
  const ms = Math.abs(h) < 1e-6 ? df(x0) : (y1 - y0) / h;
  secant.setVertices(lineThrough(x0, y0, ms));
  if (showTangent) {
    tangent.setVertices(lineThrough(x0, y0, df(x0)));
  } else {
    const p = axes.c2p(x0, y0);
    tangent.setVertices([p, p]);
  }
  runSeg.setVertices([axes.c2p(x0, y0), axes.c2p(x1, y0)]);
  riseSeg.setVertices([axes.c2p(x1, y0), axes.c2p(x1, y1)]);
  dotP.moveTo(axes.c2p(x0, y0));
  dotQ.moveTo(axes.c2p(x1, y1));
  updateInfo();
}
update();
dotP.addUpdater(() => update());

let animating = false;
async function animateToZero() {
  if (animating) return;
  animating = true;
  const start = Math.abs(h) < 0.05 ? 2 : h;
  const steps = 90;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    h = start * Math.pow(1 - t, 2);
    if (i === steps) h = 0.0;
    await scene.wait(0.03);
  }
  animating = false;
}

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'h', min: -2, max: 2.5, value: 2, step: 0.01, onChange: (v) => { if (!animating) h = v; } });
controls.addSlider({ label: 'x₀', min: 0, max: 3.5, value: 1.5, step: 0.05, onChange: (v) => { x0 = v; } });
controls.addCheckbox({ label: 'Show tangent', checked: true, onChange: (c) => { showTangent = c; } });
controls.addButton({ label: 'Animate h → 0', onClick: () => { h = 2; animateToZero(); } });

await scene.wait(0.8);
await animateToZero();

await scene.wait(999999);"}

